// Optional helper for the archive generated by tests/browser.html in --qa-write mode.
const fs=require('node:fs/promises'),path=require('node:path'),Z=require('../js/zip.js');
(async()=>{const root=path.resolve(__dirname,'../examples'),input=await fs.readFile(path.join(root,'muyu-examples.zip')),files=await Z.unpack(new Blob([input]));for(const[name,data]of Object.entries(files)){const output=path.resolve(root,name);if(!output.startsWith(root+path.sep))throw Error('无效输出路径');await fs.mkdir(path.dirname(output),{recursive:true});await fs.writeFile(output,data);}console.log('已安全解压 '+Object.keys(files).length+' 个示例文件。');})().catch(e=>{console.error(e.message);process.exitCode=1;});
